// Package i18n serves the UI strings ported from the reference (ar.json, fr.json)
// through typed keys generated by tools/i18ngen (keys_gen.go).
package i18n

import (
	_ "embed"
	"fmt"
	"regexp"
	"strings"
)

//go:generate go run ../../tools/i18ngen

//go:embed ar.json
var arJSON []byte

//go:embed fr.json
var frJSON []byte

// Key is a dotted message key; use the generated constants.
type Key string

// Locale is ar or fr.
type Locale string

// Supported locales. Arabic is the default for everyone.
const (
	AR      Locale = "ar"
	FR      Locale = "fr"
	Default        = AR
)

// Locales lists every locale in display order.
var Locales = []Locale{AR, FR}

// Meta describes how a locale is rendered.
type Meta struct {
	Dir      string // rtl | ltr
	HTMLLang string // lang attribute
	OGLocale string
	Label    string // name in its own language
}

var meta = map[Locale]Meta{
	AR: {Dir: "rtl", HTMLLang: "ar-MA", OGLocale: "ar_MA", Label: "العربية"},
	FR: {Dir: "ltr", HTMLLang: "fr-MA", OGLocale: "fr_MA", Label: "Français"},
}

// Meta returns the rendering metadata of l.
func (l Locale) Meta() Meta { return meta[l] }

// Other returns the other locale (language switcher).
func (l Locale) Other() Locale {
	if l == AR {
		return FR
	}
	return AR
}

// Parse validates a locale from a URL segment.
func Parse(s string) (Locale, bool) {
	switch Locale(s) {
	case AR, FR:
		return Locale(s), true
	}
	return "", false
}

var messages = func() map[Locale]map[string]string {
	ar, err := Flatten(arJSON)
	if err != nil {
		panic(fmt.Errorf("ar.json: %w", err))
	}
	fr, err := Flatten(frJSON)
	if err != nil {
		panic(fmt.Errorf("fr.json: %w", err))
	}
	return map[Locale]map[string]string{AR: ar, FR: fr}
}()

var placeholder = regexp.MustCompile(`\{(\w+)\}`)

// T returns the message for key in locale l, with {name} placeholders filled
// from pairs ("name", value, ...). Unknown placeholders are left as they are.
func T(l Locale, key Key, pairs ...string) string {
	s, ok := messages[l][string(key)]
	if !ok {
		// Unreachable with a generated key; keeps a visible marker otherwise.
		return string(key)
	}
	if len(pairs) < 2 || !strings.Contains(s, "{") {
		return s
	}
	values := make(map[string]string, len(pairs)/2)
	for i := 0; i+1 < len(pairs); i += 2 {
		values[pairs[i]] = pairs[i+1]
	}
	return placeholder.ReplaceAllStringFunc(s, func(m string) string {
		if v, ok := values[m[1:len(m)-1]]; ok {
			return v
		}
		return m
	})
}

// Translator binds a locale for templates.
type Translator struct{ Locale Locale }

// T translates key in the bound locale.
func (t Translator) T(key Key, pairs ...string) string { return T(t.Locale, key, pairs...) }
